"""chapter 9: サヌト→オシロガ only sorts from a cell one step north of the castle.

Owner 2026-11-24: aiming at オシロガ's bare cell camps against the cliff; the
route's sortie cell is shifted slightly up. Other routes keep the chart cell.
"""
from docich.hanjuku_speedrun import hanjuku_chart as chart
from docich.hanjuku_speedrun.hanjuku.flows import map as map_flow


def test_oshiroga_aim_is_shifted_up_for_the_sanuto_route_only():
    cell = chart.castles(9)['オシロガ']
    assert chart.aim_cell(9, 'サヌト', 'オシロガ') == (cell[0], cell[1] - 8)
    # Other routes are unchanged.
    assert chart.aim_cell(9, 'ハヤク', 'オシロガ') == cell
    assert chart.aim_cell(9, 'サヌト', 'タオ') == chart.castles(9)['タオ']
    name8, cell8 = next(iter(chart.castles(8).items()))
    assert chart.aim_cell(8, 'サヌト', name8) == cell8


def test_measured_goal_uses_the_route_offset():
    mem = {'chapter': 9, 'plan': {'orders': {}}, 'world': {}}
    order = {'step': 'I:c9:サヌト>オシロガ:1', 'source': 'サヌト', 'target': 'オシロガ',
             'purpose': 'move'}
    cell = chart.castles(9)['オシロガ']
    assert map_flow._measured_goal(mem, order, 'オシロガ') == (cell[0], cell[1] - 8)
